54	    @SuppressWarnings("resource")
55	    public static long select(boolean v, long telnetPortPid, String select) throws InputMismatchException {
56	        Map<Long, String> processMap = listProcessByJps(v);
57	        if (processMap.isEmpty()) {
58	            processMap = listProcessByJcmd();
59	            if (processMap.isEmpty()) {
60	                AnsiLog.error("Cannot find java process. Try to run `jps` or `jcmd` commands to list the instrumented Java HotSpot VMs on the target system.");
61	                return -1;
62	            }
63	        }
64	        // Put the port that is already listening at the first
65	        if (telnetPortPid > 0 && processMap.containsKey(telnetPortPid)) {
66	            String telnetPortProcess = processMap.get(telnetPortPid);
67	            processMap.remove(telnetPortPid);
68	            Map<Long, String> newProcessMap = new LinkedHashMap<Long, String>();
69	            newProcessMap.put(telnetPortPid, telnetPortProcess);
70	            newProcessMap.putAll(processMap);
71	            processMap = newProcessMap;
72	        }
73	
74	        // select target process by the '--select' option when match only one process
75	        if (select != null && !select.trim().isEmpty()) {
76	            int matchedSelectCount = 0;
77	            Long matchedPid = null;
78	            for (Entry<Long, String> entry : processMap.entrySet()) {
79	                if (entry.getValue().contains(select)) {
80	                    matchedSelectCount++;
81	                    matchedPid = entry.getKey();
82	                }
83	            }
84	            if (matchedSelectCount == 1) {
85	                return matchedPid;
86	            }
87	        }
88	
89	        AnsiLog.info("Found existing java process, please choose one and input the serial number of the process, eg : 1. Then hit ENTER.");
90	        // print list
91	        int count = 1;
92	        for (String process : processMap.values()) {
93	            if (count == 1) {
94	                System.out.println("* [" + count + "]: " + process);
95	            } else {
96	                System.out.println("  [" + count + "]: " + process);
97	            }
98	            count++;
99	        }
100	
101	        // read choice
102	        String line = new Scanner(System.in).nextLine();
103	        if (line.trim().isEmpty()) {
104	            // get the first process id
105	            return processMap.keySet().iterator().next();
106	        }
107	
108	        int choice = new Scanner(line).nextInt();
109	
110	        if (choice <= 0 || choice > processMap.size()) {
111	            return -1;
112	        }
113	
114	        Iterator<Long> idIter = processMap.keySet().iterator();
115	        for (int i = 1; i <= choice; ++i) {
116	            if (i == choice) {
117	                return idIter.next();
118	            }
119	            idIter.next();
120	        }
121	
122	        return -1;
123	    }
