125	    private static Map<Long, String> listProcessByJcmd() {
126	        Map<Long, String> result = new LinkedHashMap<>();
127	
128	        String jcmd = "jcmd";
129	        File jcmdFile = findJcmd();
130	        if (jcmdFile != null) {
131	            jcmd = jcmdFile.getAbsolutePath();
132	        }
133	
134	        AnsiLog.debug("Try use jcmd to list java process, jcmd: " + jcmd);
135	
136	        String[] command = new String[] { jcmd, "-l" };
137	
138	        List<String> lines = ExecutingCommand.runNative(command);
139	
140	        AnsiLog.debug("jcmd result: " + lines);
141	
142	        long currentPid = Long.parseLong(PidUtils.currentPid());
143	        for (String line : lines) {
144	            String[] strings = line.trim().split("\\s+");
145	            if (strings.length < 1) {
146	                continue;
147	            }
148	            try {
149	                long pid = Long.parseLong(strings[0]);
150	                if (pid == currentPid) {
151	                    continue;
152	                }
153	                if (strings.length >= 2 && isJcmdProcess(strings[1])) { // skip jcmd
154	                    continue;
155	                }
156	
157	                result.put(pid, line);
158	            } catch (Throwable e) {
159	                // https://github.com/alibaba/arthas/issues/970
160	                // ignore
161	            }
162	        }
163	        return result;
164	    }
