217	    /**
218	     * <pre>
219	     * 1. Try to find java home from System Property java.home
220	     * 2. If jdk > 8, FOUND_JAVA_HOME set to java.home
221	     * 3. If jdk <= 8, try to find tools.jar under java.home
222	     * 4. If tools.jar do not exists under java.home, try to find System env JAVA_HOME
223	     * 5. If jdk <= 8 and tools.jar do not exists under JAVA_HOME, throw IllegalArgumentException
224	     * </pre>
225	     *
226	     * @return
227	     */
228	    public static String findJavaHome() {
229	        if (FOUND_JAVA_HOME != null) {
230	            return FOUND_JAVA_HOME;
231	        }
232	
233	        String javaHome = System.getProperty("java.home");
234	
235	        if (JavaVersionUtils.isLessThanJava9()) {
236	            File toolsJar = new File(javaHome, "lib/tools.jar");
237	            if (!toolsJar.exists()) {
238	                toolsJar = new File(javaHome, "../lib/tools.jar");
239	            }
240	            if (!toolsJar.exists()) {
241	                // maybe jre
242	                toolsJar = new File(javaHome, "../../lib/tools.jar");
243	            }
244	
245	            if (toolsJar.exists()) {
246	                FOUND_JAVA_HOME = javaHome;
247	                return FOUND_JAVA_HOME;
248	            }
249	
250	            if (!toolsJar.exists()) {
251	                AnsiLog.debug("Can not find tools.jar under java.home: " + javaHome);
252	                String javaHomeEnv = System.getenv("JAVA_HOME");
253	                if (javaHomeEnv != null && !javaHomeEnv.isEmpty()) {
254	                    AnsiLog.debug("Try to find tools.jar in System Env JAVA_HOME: " + javaHomeEnv);
255	                    // $JAVA_HOME/lib/tools.jar
256	                    toolsJar = new File(javaHomeEnv, "lib/tools.jar");
257	                    if (!toolsJar.exists()) {
258	                        // maybe jre
259	                        toolsJar = new File(javaHomeEnv, "../lib/tools.jar");
260	                    }
261	                }
262	
263	                if (toolsJar.exists()) {
264	                    AnsiLog.info("Found java home from System Env JAVA_HOME: " + javaHomeEnv);
265	                    FOUND_JAVA_HOME = javaHomeEnv;
266	                    return FOUND_JAVA_HOME;
267	                }
268	
269	                throw new IllegalArgumentException("Can not find tools.jar under java home: " + javaHome
270	                        + ", please try to start arthas-boot with full path java. Such as /opt/jdk/bin/java -jar arthas-boot.jar");
271	            }
272	        } else {
273	            FOUND_JAVA_HOME = javaHome;
274	        }
275	        return FOUND_JAVA_HOME;
276	    }
