278	    public static void startArthasCore(long targetPid, List<String> attachArgs) {
279	        // find java/java.exe, then try to find tools.jar
280	        String javaHome = findJavaHome();
281	
282	        // find java/java.exe
283	        File javaPath = findJava(javaHome);
284	        if (javaPath == null) {
285	            throw new IllegalArgumentException(
286	                    "Can not find java/java.exe executable file under java home: " + javaHome);
287	        }
288	
289	        File toolsJar = findToolsJar(javaHome);
290	
291	        if (JavaVersionUtils.isLessThanJava9()) {
292	            if (toolsJar == null || !toolsJar.exists()) {
293	                throw new IllegalArgumentException("Can not find tools.jar under java home: " + javaHome);
294	            }
295	        }
296	
297	        List<String> command = new ArrayList<String>();
298	        command.add(javaPath.getAbsolutePath());
299	
300	        if (toolsJar != null && toolsJar.exists()) {
301	            command.add("-Xbootclasspath/a:" + toolsJar.getAbsolutePath());
302	        }
303	
304	        command.addAll(attachArgs);
305	        // "${JAVA_HOME}"/bin/java \
306	        // ${opts} \
307	        // -jar "${arthas_lib_dir}/arthas-core.jar" \
308	        // -pid ${TARGET_PID} \
309	        // -target-ip ${TARGET_IP} \
310	        // -telnet-port ${TELNET_PORT} \
311	        // -http-port ${HTTP_PORT} \
312	        // -core "${arthas_lib_dir}/arthas-core.jar" \
313	        // -agent "${arthas_lib_dir}/arthas-agent.jar"
314	
315	        ProcessBuilder pb = new ProcessBuilder(command);
316	        // https://github.com/alibaba/arthas/issues/2166
317	        pb.environment().put("JAVA_TOOL_OPTIONS", "");
318	        try {
319	            final Process proc = pb.start();
320	            Thread redirectStdout = new Thread(new Runnable() {
321	                @Override
322	                public void run() {
323	                    InputStream inputStream = proc.getInputStream();
324	                    try {
325	                        IOUtils.copy(inputStream, System.out);
326	                    } catch (IOException e) {
327	                        IOUtils.close(inputStream);
328	                    }
329	
330	                }
331	            });
332	
333	            Thread redirectStderr = new Thread(new Runnable() {
334	                @Override
335	                public void run() {
336	                    InputStream inputStream = proc.getErrorStream();
337	                    try {
338	                        IOUtils.copy(inputStream, System.err);
339	                    } catch (IOException e) {
340	                        IOUtils.close(inputStream);
341	                    }
342	
343	                }
344	            });
345	            redirectStdout.start();
346	            redirectStderr.start();
347	            redirectStdout.join();
348	            redirectStderr.join();
349	
350	            int exitValue = proc.exitValue();
351	            if (exitValue != 0) {
352	                AnsiLog.error("attach fail, targetPid: " + targetPid);
353	                System.exit(1);
354	            }
355	        } catch (Throwable e) {
356	            // ignore
357	        }
358	    }
