360	    public static int startArthasClient(String arthasHomeDir, List<String> telnetArgs, OutputStream out) throws Throwable {
361	        // start java telnet client
362	        // find arthas-client.jar
363	        URLClassLoader classLoader = new URLClassLoader(
364	                new URL[]{new File(arthasHomeDir, "arthas-client.jar").toURI().toURL()});
365	        Class<?> telnetConsoleClass = classLoader.loadClass("com.taobao.arthas.client.TelnetConsole");
366	        Method processMethod = telnetConsoleClass.getMethod("process", String[].class);
367	
368	        //redirect System.out/System.err
369	        PrintStream originSysOut = System.out;
370	        PrintStream originSysErr = System.err;
371	        PrintStream newOut = new PrintStream(out);
372	        PrintStream newErr = new PrintStream(out);
373	
374	        // call TelnetConsole.process()
375	        // fix https://github.com/alibaba/arthas/issues/833
376	        ClassLoader tccl = Thread.currentThread().getContextClassLoader();
377	        try {
378	            System.setOut(newOut);
379	            System.setErr(newErr);
380	            Thread.currentThread().setContextClassLoader(classLoader);
381	            return (Integer) processMethod.invoke(null, new Object[]{telnetArgs.toArray(new String[0])});
382	        } catch (Throwable e) {
383	            //java.lang.reflect.InvocationTargetException : java.net.ConnectException
384	            e = e.getCause();
385	            if (e instanceof IOException || e instanceof InterruptedException) {
386	                // ignore connection error and interrupted error
387	                return STATUS_ERROR;
388	            } else {
389	                // process error
390	                AnsiLog.error("process error: {}", e.toString());
391	                AnsiLog.error(e);
392	                return STATUS_EXEC_ERROR;
393	            }
394	        } finally {
395	            Thread.currentThread().setContextClassLoader(tccl);
396	
397	            //reset System.out/System.err
398	            System.setOut(originSysOut);
399	            System.setErr(originSysErr);
400	            //flush output
401	            newOut.flush();
402	            newErr.flush();
403	        }
404	    }
