406	    private static File findJava(String javaHome) {
407	        String[] paths = { "bin/java", "bin/java.exe", "../bin/java", "../bin/java.exe" };
408	
409	        List<File> javaList = new ArrayList<File>();
410	        for (String path : paths) {
411	            File javaFile = new File(javaHome, path);
412	            if (javaFile.exists()) {
413	                AnsiLog.debug("Found java: " + javaFile.getAbsolutePath());
414	                javaList.add(javaFile);
415	            }
416	        }
417	
418	        if (javaList.isEmpty()) {
419	            AnsiLog.debug("Can not find java/java.exe under current java home: " + javaHome);
420	            return null;
421	        }
422	
423	        // find the shortest path, jre path longer than jdk path
424	        if (javaList.size() > 1) {
425	            Collections.sort(javaList, new Comparator<File>() {
426	                @Override
427	                public int compare(File file1, File file2) {
428	                    try {
429	                        return file1.getCanonicalPath().length() - file2.getCanonicalPath().length();
430	                    } catch (IOException e) {
431	                        // ignore
432	                    }
433	                    return -1;
434	                }
435	            });
436	        }
437	        return javaList.get(0);
438	    }
