441	        if (JavaVersionUtils.isGreaterThanJava8()) {
442	            return null;
443	        }
444	
445	        File toolsJar = new File(javaHome, "lib/tools.jar");
446	        if (!toolsJar.exists()) {
447	            toolsJar = new File(javaHome, "../lib/tools.jar");
448	        }
449	        if (!toolsJar.exists()) {
450	            // maybe jre
451	            toolsJar = new File(javaHome, "../../lib/tools.jar");
452	        }
453	
454	        if (!toolsJar.exists()) {
455	            throw new IllegalArgumentException("Can not find tools.jar under java home: " + javaHome);
456	        }
457	
458	        AnsiLog.debug("Found tools.jar: " + toolsJar.getAbsolutePath());
459	        return toolsJar;
460	    }
