462	    private static File findJcmd() {
463	        // Try to find jcmd under java.home and System env JAVA_HOME
464	        String javaHome = System.getProperty("java.home");
465	        String[] paths = { "bin/jcmd", "bin/jcmd.exe", "../bin/jcmd", "../bin/jcmd.exe" };
466	
467	        List<File> jcmdList = new ArrayList<>();
468	        for (String path : paths) {
469	            File jcmdFile = new File(javaHome, path);
470	            if (jcmdFile.exists()) {
471	                AnsiLog.debug("Found jcmd: " + jcmdFile.getAbsolutePath());
472	                jcmdList.add(jcmdFile);
473	            }
474	        }
475	
476	        if (jcmdList.isEmpty()) {
477	            AnsiLog.debug("Can not find jcmd under :" + javaHome);
478	            String javaHomeEnv = System.getenv("JAVA_HOME");
479	            AnsiLog.debug("Try to find jcmd under env JAVA_HOME :" + javaHomeEnv);
480	            if (javaHomeEnv != null) {
481	                for (String path : paths) {
482	                    File jcmdFile = new File(javaHomeEnv, path);
483	                    if (jcmdFile.exists()) {
484	                        AnsiLog.debug("Found jcmd: " + jcmdFile.getAbsolutePath());
485	                        jcmdList.add(jcmdFile);
486	                    }
487	                }
488	            } else {
489	                AnsiLog.debug("JAVA_HOME environment variable is not set.");
490	            }
491	        }
492	
493	        if (jcmdList.isEmpty()) {
494	            AnsiLog.debug("Can not find jcmd under current java home: " + javaHome);
495	            return null;
496	        }
497	
498	        // find the shortest path, jre path longer than jdk path
499	        if (jcmdList.size() > 1) {
500	            jcmdList.sort((file1, file2) -> {
501	                try {
502	                    return file1.getCanonicalPath().length() - file2.getCanonicalPath().length();
503	                } catch (IOException e) {
504	                    // ignore
505	                    // fallback to absolute path length comparison
506	                    return file1.getAbsolutePath().length() - file2.getAbsolutePath().length();
507	                }
508	            });
509	        }
510	        return jcmdList.get(0);
511	    }
512	
513	    private static boolean isJcmdProcess(String mainClassName) {
514	        // Java 8 or Java 9+
515	        return "sun.tools.jcmd.JCmd".equals(mainClassName) || "jdk.jcmd/sun.tools.jcmd.JCmd".equals(mainClassName);
516	    }
